-- 498_nightly_look_approvals.sql — the approval matrix as DATA (Kevin 2026-09-12: "we can go with that and come up
-- with a clean architecture that lets each nightly choose from the pool of models and looks based on if it's a dual
-- or single character dream").
--
-- One row per (look × model × surface) graded in the fixed-scene matrix (NIGHTLY_LOOK_TALLY.md rounds 1-3; verdicts
-- by eye per surface; `source = 'override'` = Kevin's call). The nightly resolver (NIGHTLY_LOOKS_REFACTOR_PLAN.md
-- §2) will pick the MODEL from nightly_model_policy for the render's surface, then roll a LOOK from
--   SELECT look_key FROM nightly_look_approvals WHERE model = <picked> AND surface = <couple|solo> AND approved
-- so a dual dream and a single dream each draw from their own (model × look) pool. `dream_mediums.nightly_surfaces`
-- stays as the model-agnostic UNION (used by the pin route + the QA runner) and is refreshed from this table here.
-- Regenerate rows after any future matrix round: `node scripts/qa-nightly-looks-compare.js --registry` writes the
-- doc; this table is the runtime copy of the same grades (a future script can emit the INSERT block).
CREATE TABLE IF NOT EXISTS public.nightly_look_approvals (
  look_key   text NOT NULL REFERENCES public.dream_mediums(key) ON DELETE CASCADE,
  model      text NOT NULL,
  surface    text NOT NULL CHECK (surface IN ('couple','solo')),
  approved   boolean NOT NULL DEFAULT false,
  source     text NOT NULL DEFAULT 'matrix' CHECK (source IN ('matrix','override')),
  note       text,
  graded_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (look_key, model, surface)
);
ALTER TABLE public.nightly_look_approvals ENABLE ROW LEVEL SECURITY;
-- Engine-only table: no client policies (service role bypasses RLS). Read by the nightly render and QA scripts.
GRANT SELECT ON public.nightly_look_approvals TO service_role;

ON CONFLICT (look_key, model, surface) DO UPDATE SET
  approved = EXCLUDED.approved, source = EXCLUDED.source, note = EXCLUDED.note, graded_at = now();

-- nightly_surfaces = the union of approved surfaces across models (model-agnostic; the pin route + QA runner read it).
UPDATE public.dream_mediums m SET nightly_surfaces = COALESCE((
  SELECT array_agg(DISTINCT a.surface ORDER BY a.surface) FROM public.nightly_look_approvals a
  WHERE a.look_key = m.key AND a.approved
), '{}'::text[]), is_active = true
WHERE m.nightly_look AND m.key LIKE 'nightly\_%';
-- A look with no approval anywhere stays parked (empty surfaces) but active for re-testing via force_look.
